<?php
function lop_review_components(mysqli $db,array $catalog,array $cfg): void {
    global $id;$groups=[];$used=[];$masters=lf_rows($db,'SELECT id,nama FROM master_biaya_lain ORDER BY nama');
    if(lma_enabled($cfg))$catalog['components']=lma_catalog_components($catalog['components']);
    foreach($catalog['components'] as $c){$key=$c['group_key']??$c['key'];$groups[$key]??=['name'=>$c['name'],'rows'=>[],'count'=>0,'total'=>0];$groups[$key]['rows'][]=$c;$groups[$key]['count']+=$c['count'];if($c['total']!==null)$groups[$key]['total']+=lf_cents($c['total']);if(!empty($c['source_code']))$used[$c['source_code']]=true;}
    $page=max(1,(int)($_GET['page']??1));
    echo '<section class="dbt-card"><h2>Komponen pembayaran</h2><p>Nama mengikuti master Legacy. Histori memakai nominal pembayaran asli; master baru dibuat nonaktif tanpa menerbitkan tagihan.</p><div class="lop-group-list">';
    foreach(array_slice($groups,($page-1)*15,15) as $group){$c=$group['rows'][0];$proposalKey=$c['proposal_key'];$proposal=$cfg['new_masters'][$proposalKey]??[];$map=$cfg['components'][$c['key']]??[];$history=lful_history_category($c['key']);$selected=$map['category']??($c['suggestion']?:$history);if(str_starts_with($selected,'biaya_baru:')){$proposalKey=substr($selected,11);$proposal=$cfg['new_masters'][$proposalKey]??$proposal;}
        $existing=null;foreach($masters as $m)if(mb_strtolower(trim($m['nama']))===mb_strtolower(trim($c['name']))){$existing=$m;break;}
        echo '<details class="lf-debt"><summary><span>'.loe($group['name']).(!empty($map['confirmed'])?' ? Disetujui':'').'</span><span class="lop-count">'.$group['count'].' rincian ? '.loe(legacy_ui_money(lf_money($group['total']))).'</span></summary><div class="lop-group-body"><p>'.(isset($c['source_code'])?'Kode Legacy: '.loe($c['source_code']?:'Tidak tercatat').' ? ':'').'Total histori berbeda dari tarif penagihan.</p>';
        if(!empty($c['ambiguous'])&&empty($map['accepted_source_names']))echo '<p class="dbt-warning">Kode ini memiliki beberapa nama. Pilih arti yang sesuai bukti sebelum menerapkan.</p>';
        echo '<p class="dbt-info">Rekomendasi: '.($existing?'gunakan master '.loe($existing['nama']):'siapkan master '.loe($c['name']).' ? Nonaktif').'</p><form method="post" class="lf-form">';lop_form_hidden('components');
        foreach($group['rows'] as $item){$key=$item['key'];$mapping=$cfg['components'][$key]??$map;$chosen=$mapping['category']??$selected;$h=lful_history_category($key);$options=['spp'=>'SPP','komite'=>'Komite','daftar_ulang'=>'Daftar Ulang','psb'=>'PSB',$h=>'Histori Saja'];foreach($masters as $m)$options['biaya_lain:'.$m['id']]=$m['nama'];$options['biaya_baru:'.$proposalKey]='Siapkan Master Baru: '.$c['name'];foreach($cfg['new_masters']??[] as $otherKey=>$other)if($otherKey!==$proposalKey&&!empty($other['name']))$options['biaya_baru:'.$otherKey]='Gunakan Usulan: '.$other['name'];if($item['savings'])$options=['savings_reference'=>'Referensi tabungan'];if(strtoupper($item['column'])==='U_SORGA'){$options=['komite'=>'Komite (POMG)'];$chosen='komite';}
            echo '<label>Tujuan '.loe($item['column']).' ? '.(int)$item['count'].' rincian<select name="components['.loe($key).'][category]">';foreach($options as $value=>$label)echo '<option value="'.loe($value).'"'.($chosen===$value?' selected':'').'>'.loe($label).'</option>';echo '</select></label>';
            if(!empty($item['ambiguous'])&&!empty($mapping['accepted_source_names'])){echo '<p class="dbt-info">Nama sumber dipertahankan: '.loe(implode(' / ',$mapping['accepted_source_names'])).'.</p>';foreach($mapping['accepted_source_names'] as $name)echo '<input type="hidden" name="components['.loe($key).'][accepted_source_names][]" value="'.loe($name).'">';}elseif(!empty($item['ambiguous'])){echo '<label>Nama sumber yang disahkan<select required name="components['.loe($key).'][source_name]"><option value="">Pilih nama sesuai bukti</option>';foreach($item['source_names'] as $name)echo '<option '.(($mapping['source_name']??'')===$name?'selected':'').' value="'.loe($name).'">'.loe($name).'</option>';echo '</select></label>';}
            echo '<label>Bukti pemetaan<textarea name="components['.loe($key).'][reason]" minlength="10" maxlength="1000" required>'.loe($mapping['reason']??$cfg['accounting_reason']??'').'</textarea></label><label class="lop-check"><input type="checkbox" name="components['.loe($key).'][confirmed]" value="1" '.(!empty($mapping['confirmed'])?'checked':'').' required><span>Saya mengesahkan pemetaan rincian ini.</span></label>';
        }
        echo '<details class="lop-proposal"><summary>Siapkan master baru</summary><div class="lop-group-body"><div class="lful-grid"><label>Nama master<input name="new_masters['.$proposalKey.'][name]" maxlength="100" value="'.loe($proposal['name']??$c['name']).'"></label><label>Tarif (kosongkan jika belum diketahui)<input name="new_masters['.$proposalKey.'][nominal]" inputmode="decimal" value="'.loe($proposal['nominal']??'').'"></label></div><label class="lop-check"><input type="checkbox" name="new_masters['.$proposalKey.'][tariff_pending]" value="1" '.(($proposal['tariff_pending']??true)?'checked':'').'><span>Tarif belum ditetapkan. Master tetap nonaktif sampai tarif positif diisi.</span></label><label>Bukti / alasan master<textarea name="new_masters['.$proposalKey.'][reason]" maxlength="1000">'.loe($proposal['reason']??'Mengikuti nama komponen pada sumber Legacy yang diperiksa.').'</textarea></label><label class="lop-check"><input type="checkbox" name="new_masters['.$proposalKey.'][confirmed]" value="1" '.(!empty($proposal['confirmed'])?'checked':'').'><span>Saya mengesahkan master baru nonaktif ini.</span></label></div></details><details><summary>Rincian sumber</summary><div class="lop-group-body">';
        foreach($group['rows'] as $item){echo '<p>'.loe($item['table']).' / '.loe($item['column']).' ? Rentang '.loe(legacy_ui_money($item['minimum'])).' ? '.loe(legacy_ui_money($item['maximum'])).'</p>';foreach($item['evidence'] as $e)echo '<p>Identitas '.loe($e['student']??'Tidak tercatat').' ? '.loe($e['date']??'Tanggal tidak tercatat').' ? '.loe(legacy_ui_money($e['amount'])).'</p>';}
        echo '</div></details><button class="dbt-button dbt-button-primary">'.legacy_ui_icon('save').' Simpan Komponen</button></form></div></details>';
    }
    echo '</div><nav class="legacy-actions">';foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $d=>$label){$p=$page+$d;if($p>0&&($p-1)*15<count($groups))echo '<a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'components','page'=>$p])).'">'.$label.'</a>';}echo '</nav></section>';
    $unused=array_diff_key($catalog['source_fee_masters']??[],$used);if($unused){echo '<section class="dbt-card"><h2>Master sumber belum digunakan</h2><p>Tidak ada rincian pembayaran untuk kode berikut. Tidak ditambahkan ke total histori.</p><ul class="lop-unused">';foreach($unused as $code=>$names)echo '<li><strong>'.loe(implode(' / ',$names)).'</strong><span>Kode '.loe($code).' ? Belum digunakan</span></li>';echo '</ul></section>';}
}
